__NUXT_JSONP__("/think-tanks/eventos/de_lo_global_a_lo_local_el_informe_estado_del_sector_2024_de_on_think_tanks_y_los_retos_de_las_osc_en_mexico", (function(a,b,c,d,e,f,g,h,i,j){return {data:[{post:{slug:"de_lo_global_a_lo_local_el_informe_estado_del_sector_2024_de_on_think_tanks_y_los_retos_de_las_osc_en_mexico",title:"De lo global a lo local: el Informe Estado del Sector 2024 de On Think Tanks y los retos de las OSC en México",date:"2024-12-05T21:41:16.491Z",img:"https:\u002F\u002Fucarecdn.com\u002F8582dca3-5b85-40ce-a62c-6ba3f7cfc95b\u002F","img-alt":"State of the sector On Think Tanks",autor:"Ethos",category:"think-tanks",extracto:"En el panel  “State of the Sector: Potenciando las voces locales”, organizaciones de la sociedad civil en México dialogaron sobre los hallazgos del informe de On Think Tanks, así como los retos y oportunidades que enfrentan a nivel local.",toc:[],body:{type:"root",children:[{type:b,tag:c,props:{},children:[{type:a,value:"En coordinación con On Think Tanks, Ethos realizó el panel “State of the Sector: Potenciando las voces locales”, en el que se presentaron los retos globales del informe State of the Sector 2024 así como la situación que se vive en México a nivel local. Participaron Marlene León, de Iniciativa Sinaloa; Jesús Tadeo Manrique, de En Igualdad A.C.; Yeddeli Cupul, de Ciudadanxs por la transparencia; Marco Antonio Zamarripa, del CCI Laguna; y Lourdes Bayona, de Solidaria México."}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"En su mensaje de bienvenida, Liliana Alvarado, directora general de Ethos, expresó que el informe ofrece un panorama global de los retos y oportunidades de dichas organizaciones. En este sentido, señaló que en México y América Latina los think tanks son más necesarios que nunca, aunque las condiciones en las que trabajan se han vuelto un tanto complejas, debido a la falta de financiamiento, la polarización política y la reducción del espacio cívico. Por ello, los think tanks deben fortalecer su resiliencia y tomar en cuenta el contexto para adaptarse, mantenerse y seguir incidiendo."}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"Posteriormente, Estefanía Terán, directora de On Think Tanks, compartió que a nivel global, para 79% de los think tanks uno de los principales desafíos es la adaptabilidad, seguido del financiamiento (59%). Mientras que para América Latina y El Caribe, el reto más importante son las transiciones de liderazgo político."}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"Respecto a lo que ocurre en México, Javier González, director de Desarrollo Institucional en Ethos, indicó que la disminución del financiamiento ha impactado en la investigación de los think tanks. “La agenda está cada vez más condicionada por las prioridades de los donantes y el financiamiento a corto plazo”, puntualizó."}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"En la conversación con las organizaciones locales, las y los panelistas coincidieron en que el contexto político ha dificultado su labor y comparten la preocupación por el financiamiento, que cada vez se enfoca más en proyectos a corto plazo. Asimismo, señalaron que han tenido que adaptarse al contexto, cuidando de conservar su esencia, y apoyarse de la creatividad, así como de las nuevas tecnologías."}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"Aquí puedes consultar el "},{type:b,tag:e,props:{href:"https:\u002F\u002Fbit.ly\u002F3CyAlKG",rel:[f,g,h],target:i},children:[{type:a,value:"informe de On Think Tanks"}]},{type:a,value:" y también el análisis particular de nuestro país: "},{type:b,tag:e,props:{href:"https:\u002F\u002Fbit.ly\u002F3YVnZnA",rel:[f,g,h],target:i},children:[{type:a,value:"México, entre la fragilidad y la adaptabilidad"}]},{type:a,value:", de Javier González."}]}]},dir:"\u002Feventos",path:"\u002Feventos\u002Fde_lo_global_a_lo_local_el_informe_estado_del_sector_2024_de_on_think_tanks_y_los_retos_de_las_osc_en_mexico",extension:".md",createdAt:j,updatedAt:j}}],fetch:{},mutations:[]}}("text","element","p","\n","a","nofollow","noopener","noreferrer","_blank","2025-04-23T06:21:15.372Z")));